style.css:
body {
    background-image: url('https://i.postimg.cc/25WT4998/a46a9vvv.jpg'); /* Sostituisci con il tuo link */
    background-repeat: no-repeat;
    background-size: cover;
    background-position: center center;
    background-attachment: fixed;
    filter: blur(2px); /* Sfocatura leggera dello sfondo */
    transition: filter 0.5s ease, background 0.5s ease;
}

/* Overlay semitrasparente per migliorare leggibilità */
body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.4); /* Nero trasparente */
    pointer-events: none;
}

/* Testo più leggibile con ombra e transizione colore */
body, p, h1, h2, h3, h4, h5, h6 {
    color: #ffffff;
    text-shadow: 2px 2px 5px rgba(0,0,0,0.7);
    transition: color 0.3s ease, text-shadow 0.3s ease;
}

/* Effetto hover sui link */
a {
    color: #ffcc00;
    transition: color 0.3s ease, text-shadow 0.3s ease;
}

a:hover {
    color: #ffffff;
    text-shadow: 2px 2px 8px rgba(255,255,255,0.8);
}

/* Pulsante di esempio con effetto leggero */
button {
    background: rgba(255, 255, 255, 0.2);
    border: 1px solid #ffffff;
    color: #ffffff;
    padding: 8px 16px;
    border-radius: 8px;
    transition: background 0.3s ease, transform 0.2s ease;
}

button:hover {
    background: rgba(255, 255, 255, 0.4);
    transform: scale(1.05);
}
